import Database from "better-sqlite3";
import path from "path";

const DB_PATH = path.join(process.cwd(), "data", "recruiting.db");
const db = new Database(DB_PATH);
db.pragma("journal_mode = WAL");

db.exec(`
  UPDATE permissions SET resource = 'dashboard'
  WHERE resource IN ('dashboard.summary', 'dashboard.allocation', 'dashboard.progress');

  UPDATE permissions SET resource = 'admin.data'
  WHERE resource IN ('admin.data-sheet', 'admin.workflow');

  DELETE FROM permissions WHERE id NOT IN (
    SELECT MIN(id) FROM permissions GROUP BY role, resource, action
  );

  INSERT OR IGNORE INTO permissions (role, resource, action, allowed) VALUES
    ('ADMIN', 'workflow.review', 'view', 0),
    ('ADMIN', 'workflow.review', 'edit', 0),
    ('ADMIN', 'workflow.advance', 'view', 1),
    ('ADMIN', 'workflow.advance', 'edit', 1),
    ('DEAN', 'workflow.review', 'view', 0),
    ('DEAN', 'workflow.review', 'edit', 0),
    ('DEAN', 'workflow.advance', 'view', 0),
    ('DEAN', 'workflow.advance', 'edit', 0);
`);

console.log("Resource migration complete.");
db.close();

import Database from "better-sqlite3";
import path from "path";

const DB_PATH = path.join(process.cwd(), "data", "recruiting.db");
const db = new Database(DB_PATH);
db.pragma("journal_mode = WAL");

db.exec(`
  CREATE TABLE IF NOT EXISTS review_decisions (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    request_id INTEGER NOT NULL,
    candidate_id INTEGER NOT NULL,
    step_key TEXT NOT NULL,
    reviewer_id INTEGER NOT NULL,
    decision TEXT,
    comment TEXT,
    review_data_json TEXT DEFAULT '{}',
    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
    updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (request_id) REFERENCES recruitment_requests (id) ON DELETE CASCADE,
    FOREIGN KEY (candidate_id) REFERENCES candidate_profiles (id) ON DELETE CASCADE,
    FOREIGN KEY (reviewer_id) REFERENCES users (id) ON DELETE CASCADE,
    UNIQUE(request_id, candidate_id, step_key, reviewer_id)
  );
`);

console.log("review_decisions table created.");
db.close();

import { getDb } from "./db";

export interface ReviewDecision {
  id: number;
  requestId: number;
  candidateId: number;
  stepKey: string;
  reviewerId: number;
  decision: string | null;
  comment: string | null;
  reviewDataJson: string;
  createdAt: string;
  updatedAt: string;
}

interface ReviewDecisionRow {
  id: number;
  request_id: number;
  candidate_id: number;
  step_key: string;
  reviewer_id: number;
  decision: string | null;
  comment: string | null;
  review_data_json: string;
  created_at: string;
  updated_at: string;
}

function mapRow(row: ReviewDecisionRow): ReviewDecision {
  return {
    id: row.id,
    requestId: row.request_id,
    candidateId: row.candidate_id,
    stepKey: row.step_key,
    reviewerId: row.reviewer_id,
    decision: row.decision,
    comment: row.comment,
    reviewDataJson: row.review_data_json,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

export function getReviewDecisions(
  requestId: number,
  stepKey?: string
): ReviewDecision[] {
  const db = getDb();

  if (stepKey) {
    const rows = db
      .prepare(
        "SELECT * FROM review_decisions WHERE request_id = ? AND step_key = ? ORDER BY created_at"
      )
      .all(requestId, stepKey) as ReviewDecisionRow[];
    return rows.map(mapRow);
  }

  const rows = db
    .prepare(
      "SELECT * FROM review_decisions WHERE request_id = ? ORDER BY step_key, created_at"
    )
    .all(requestId) as ReviewDecisionRow[];
  return rows.map(mapRow);
}

export function getReviewDecisionById(id: number): ReviewDecision | null {
  const db = getDb();
  const row = db
    .prepare("SELECT * FROM review_decisions WHERE id = ?")
    .get(id) as ReviewDecisionRow | undefined;
  return row ? mapRow(row) : null;
}

export function createReviewDecision(data: {
  requestId: number;
  candidateId: number;
  stepKey: string;
  reviewerId: number;
  decision?: string | null;
  comment?: string | null;
  reviewDataJson?: string;
}): ReviewDecision {
  const db = getDb();
  const stmt = db.prepare(`
    INSERT INTO review_decisions (request_id, candidate_id, step_key, reviewer_id, decision, comment, review_data_json)
    VALUES (?, ?, ?, ?, ?, ?, ?)
    ON CONFLICT(request_id, candidate_id, step_key, reviewer_id)
    DO UPDATE SET
      decision = excluded.decision,
      comment = excluded.comment,
      review_data_json = excluded.review_data_json,
      updated_at = CURRENT_TIMESTAMP
  `);

  const result = stmt.run(
    data.requestId,
    data.candidateId,
    data.stepKey,
    data.reviewerId,
    data.decision ?? null,
    data.comment ?? null,
    data.reviewDataJson ?? "{}"
  );

  // On conflict, the rowid returned is 0; fetch by unique key instead
  if (result.changes > 0 && result.lastInsertRowid === 0) {
    const row = db
      .prepare(
        "SELECT * FROM review_decisions WHERE request_id = ? AND candidate_id = ? AND step_key = ? AND reviewer_id = ?"
      )
      .get(data.requestId, data.candidateId, data.stepKey, data.reviewerId) as ReviewDecisionRow;
    return mapRow(row);
  }

  return getReviewDecisionById(Number(result.lastInsertRowid))!;
}

export function updateReviewDecision(
  id: number,
  data: {
    decision?: string | null;
    comment?: string | null;
    reviewDataJson?: string;
  }
): ReviewDecision | null {
  const db = getDb();

  const fields: string[] = [];
  const values: unknown[] = [];

  if (data.decision !== undefined) {
    fields.push("decision = ?");
    values.push(data.decision);
  }
  if (data.comment !== undefined) {
    fields.push("comment = ?");
    values.push(data.comment);
  }
  if (data.reviewDataJson !== undefined) {
    fields.push("review_data_json = ?");
    values.push(data.reviewDataJson);
  }

  if (fields.length === 0) return getReviewDecisionById(id);

  fields.push("updated_at = CURRENT_TIMESTAMP");
  values.push(id);

  db.prepare(`UPDATE review_decisions SET ${fields.join(", ")} WHERE id = ?`).run(
    ...values
  );

  return getReviewDecisionById(id);
}

export function allCandidatesReviewed(
  requestId: number,
  stepKey: string
): boolean {
  const db = getDb();

  const candidateCount = db
    .prepare(
      "SELECT COUNT(*) as count FROM candidate_profiles WHERE request_id = ?"
    )
    .get(requestId) as { count: number };

  if (candidateCount.count === 0) return false;

  const reviewedCount = db
    .prepare(
      "SELECT COUNT(DISTINCT candidate_id) as count FROM review_decisions WHERE request_id = ? AND step_key = ? AND decision IS NOT NULL"
    )
    .get(requestId, stepKey) as { count: number };

  return reviewedCount.count >= candidateCount.count;
}

