import Database from "better-sqlite3";
import path from "path";

const DB_PATH = path.join(process.cwd(), "data", "recruiting.db");
const db = new Database(DB_PATH);
db.pragma("journal_mode = WAL");

// Use a transaction so we can safely delete old rows and insert consolidated ones
const migrate = db.transaction(() => {
  // 1. For dashboard consolidation: keep one row per (role, action) with MAX(allowed),
  //    then delete the old sub-resource rows
  const dashboardRows = db
    .prepare(
      `SELECT role, action, MAX(allowed) as allowed
       FROM permissions
       WHERE resource IN ('dashboard.summary', 'dashboard.allocation', 'dashboard.progress')
       GROUP BY role, action`
    )
    .all() as { role: string; action: string; allowed: number }[];

  db.prepare(
    `DELETE FROM permissions WHERE resource IN ('dashboard.summary', 'dashboard.allocation', 'dashboard.progress')`
  ).run();

  const insertStmt = db.prepare(
    `INSERT OR IGNORE INTO permissions (role, resource, action, allowed) VALUES (?, ?, ?, ?)`
  );
  for (const row of dashboardRows) {
    insertStmt.run(row.role, "dashboard", row.action, row.allowed);
  }

  // 2. For admin consolidation
  const adminRows = db
    .prepare(
      `SELECT role, action, MAX(allowed) as allowed
       FROM permissions
       WHERE resource IN ('admin.data-sheet', 'admin.workflow')
       GROUP BY role, action`
    )
    .all() as { role: string; action: string; allowed: number }[];

  db.prepare(
    `DELETE FROM permissions WHERE resource IN ('admin.data-sheet', 'admin.workflow')`
  ).run();

  for (const row of adminRows) {
    insertStmt.run(row.role, "admin.data", row.action, row.allowed);
  }

  // 3. Insert new workflow permissions
  db.exec(`
    INSERT OR IGNORE INTO permissions (role, resource, action, allowed) VALUES
      ('ADMIN', 'workflow.review', 'view', 0),
      ('ADMIN', 'workflow.review', 'edit', 0),
      ('ADMIN', 'workflow.advance', 'view', 1),
      ('ADMIN', 'workflow.advance', 'edit', 1),
      ('DEAN', 'workflow.review', 'view', 0),
      ('DEAN', 'workflow.review', 'edit', 0),
      ('DEAN', 'workflow.advance', 'view', 0),
      ('DEAN', 'workflow.advance', 'edit', 0);
  `);
});

migrate();

console.log("Resource migration complete.");
db.close();
